func (app application) runAnalyze(arguments []string, stdout, stderr io.Writer) int {
	return runAnalyzeWith(arguments, stdout, stderr, analyzeDependencies{
		toolchain: app.installedToolchain,
		identity:  target.ReadToolchainIdentity, workingDirectory: os.Getwd,
		inspect: preparation.Inspect, build: capabilityanalysis.Build,
	})
}

func (app application) install(explicitToolchainRoot string) (installation, error) {
	if app.cache != nil && app.cache.set && app.cache.explicitRoot == explicitToolchainRoot {
		return app.cache.installed, nil
	}
	executable := ""
	if app.cache != nil && app.cache.identitySet {
		executable = app.cache.executable
	} else {
		var err error
		executable, err = app.executablePath()
		if err != nil {
			return installation{}, err
		}
		executable, err = absoluteExecutable(executable)
		if err != nil {
			return installation{}, err
		}
	}
	resolved, err := app.resolveInstallation(executable, explicitToolchainRoot)
	if err != nil {
		return installation{}, fmt.Errorf("resolve Gomad installation: %w", err)
	}
	build := ""
	if app.cache != nil && app.cache.identitySet {
		build = app.cache.runnerBuild
	} else {
		digest, err := digestRunner(executable)
		if err != nil {
			return installation{}, fmt.Errorf("hash gomad executable: %w", err)
		}
		build = string(digest)
	}
	installed := installation{toolchainRoot: resolved.ToolchainRoot, executable: executable, runnerBuild: build}
	if app.cache != nil {
		app.cache.explicitRoot, app.cache.installed, app.cache.set = explicitToolchainRoot, installed, true
		app.cache.executable, app.cache.runnerBuild, app.cache.identitySet = executable, build, true
	}
	return installed, nil
}

// installedToolchain resolves only the toolchain root, for operations that
// start no Runner child process.

func (app application) installedToolchain(explicitToolchainRoot string) (string, error) {
	resolved, err := app.install(explicitToolchainRoot)
	return resolved.toolchainRoot, err
}

// digestRunner is the Runner build identity of the gomad executable at path.

func (app application) runCampaignShard(arguments []string, stdout, stderr io.Writer) int {
	return runCampaignShardWith(arguments, stdout, stderr, campaignShardDependencies{install: app.install, run: runner.RunCampaignShard})
}

func runCampaignShardWith(arguments []string, stdout, stderr io.Writer, dependencies campaignShardDependencies) int {
	flags := flag.NewFlagSet("gomad execute-shard", flag.ContinueOnError)
	flags.SetOutput(stderr)
	shardValue := flags.String("shard", "", "zero-based INDEX/COUNT shard assignment")
	artifacts := flags.String("artifacts", ".gomad/artifacts", "artifact root")
	toolchainRoot := flags.String("toolchain-root", "", "absolute pinned toolchain root")
	jsonOutput := flags.Bool("json", false, "emit stable JSON events")
	if err := flags.Parse(arguments); err != nil {
		return 2
	}
	if flags.NArg() != 1 {
		fmt.Fprint(stderr, usage)
		return 2
	}
	shard, err := parseCampaignShard(*shardValue)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	installed, err := dependencies.install(*toolchainRoot)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 3
	}
	reporter := newExploreReporter(*jsonOutput, stdout, stderr)
	result, err := dependencies.run(context.Background(), runner.CampaignShardSpec{
		PlanPath: flags.Arg(0), Shard: shard, Artifacts: *artifacts, ToolchainRoot: installed.toolchainRoot, RunnerBuild: installed.runnerBuild,
		SupervisorCommand: installed.supervisorCommand(), Progress: reporter.Progress, ProgressInterval: 5 * time.Second,
	})
	if err != nil {
		classification := classifyExploreError(err)
		if writeErr := reporter.Error(classification, err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return 3
		}
		return exploreErrorStatus(classification)
	}
	if err := reporter.Result(result); err != nil {
		fmt.Fprintln(stderr, err)
		return 3
	}
	if result.Failures != 0 {
		return 1
	}
	return 0
}

func (app application) run(arguments []string, stdout, stderr io.Writer) int {
	if len(arguments) == 0 {
		fmt.Fprint(stderr, usage)
		return 2
	}
	if isPrivateMode(arguments[0]) {
		return app.runPrivateMode(arguments[0], stderr)
	}
	switch arguments[0] {
	case "explore":
		return app.runExplore(arguments[1:], stdout, stderr)
	case "plan":
		return app.runPlan(arguments[1:], stdout, stderr)
	case "execute-shard":
		return app.runCampaignShard(arguments[1:], stdout, stderr)
	case "merge":
		return runMergeCampaigns(arguments[1:], stdout, stderr)
	case "qualify":
		return app.runQualify(arguments[1:], stdout, stderr)
	case "qualify-set":
		return app.runQualifySet(arguments[1:], stdout, stderr)
	case "merge-set":
		return runMergeSet(arguments[1:], stdout, stderr)
	case "compare-support":
		return runCompareSupport(arguments[1:], stdout, stderr)
	case "analyze":
		return app.runAnalyze(arguments[1:], stdout, stderr)
	case "resume":
		return app.runResume(arguments[1:], stdout, stderr)
	case "recover":
		return runRecover(arguments[1:], stdout, stderr)
	case "replay":
		return app.runReplay(arguments[1:], stdout, stderr)
	case "minimize":
		return app.runMinimize(arguments[1:], stdout, stderr)
	case "doctor":
		return app.runDoctor(arguments[1:], stdout, stderr)
	case "inspect":
		return runInspect(arguments[1:], stdout, stderr)
	default:
		fmt.Fprintf(stderr, "unknown gomad command %q\n%s", arguments[0], usage)
		return 2
	}
}

func (app application) runDoctor(arguments []string, stdout, stderr io.Writer) int {
	flags := flag.NewFlagSet("gomad doctor", flag.ContinueOnError)
	flags.SetOutput(stderr)
	artifacts := flags.String("artifacts", ".gomad/artifacts", "artifact root to verify")
	toolchainRoot := flags.String("toolchain-root", "", "absolute pinned toolchain root")
	jsonOutput := flags.Bool("json", false, "emit stable JSON")
	if err := flags.Parse(arguments); err != nil {
		return 2
	}
	if flags.NArg() != 0 {
		fmt.Fprint(stderr, usage)
		return 2
	}
	executable, err := app.executablePath()
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 3
	}
	executable, err = absoluteExecutable(executable)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 3
	}
	artifactRoot, err := filepath.Abs(*artifacts)
	if err != nil {
		fmt.Fprintf(stderr, "resolve artifact directory: %v\n", err)
		return 2
	}
	resolved, err := app.resolveInstallation(executable, *toolchainRoot)
	if err != nil {
		if _, writeErr := fmt.Fprintf(stderr, "resolve Gomad installation: %v\n", err); writeErr != nil {
			return 3
		}
		return 2
	}
	report := Check(Config{
		ToolchainRoot: resolved.ToolchainRoot, InstallationSource: resolved.Source, RepairInstruction: resolved.RepairInstruction,
		RunnerPath: executable, ArtifactRoot: artifactRoot, HostOS: runtime.GOOS, HostArch: runtime.GOARCH,
	})
	if *jsonOutput {
		encoded, marshalErr := json.Marshal(report)
		if marshalErr != nil {
			fmt.Fprintf(stderr, "encode doctor report: %v\n", marshalErr)
			return 3
		}
		fmt.Fprintf(stdout, "%s\n", encoded)
	} else {
		fmt.Fprintf(stdout, "gomad doctor: available=%t host=%s go=%s toolchain=%s runner=%s boundary=%s\n", report.Available, report.Host, report.GoVersion, report.ToolchainBuild, report.RunnerBuild, report.BoundaryManifestVersion)
		for _, check := range report.Checks {
			fmt.Fprintf(stdout, "%-10s %-5s %s\n", check.Name, check.Status, check.Detail)
		}
		if _, err := fmt.Fprintf(stdout, "installation: source=%s toolchain=%s\nrepair: %s\n", report.InstallationSource, report.ToolchainRoot, report.RepairInstruction); err != nil {
			return 3
		}
	}
	if !report.Available {
		return 1
	}
	return 0
}

type exploreDependencies struct {
	install          func(string) (installation, error)
	workingDirectory func() (string, error)
	explore          func(context.Context, runner.CampaignSpec) (runner.CampaignResult, error)
	plan             func(context.Context, runner.CampaignPlanSpec) (runner.CampaignPlanResult, error)
}

func (app application) exploreDependencies() exploreDependencies {
	return exploreDependencies{install: app.install, workingDirectory: os.Getwd, explore: runner.Explore, plan: runner.CreateCampaignPlan}
}

func (app application) runExplore(arguments []string, stdout, stderr io.Writer) int {
	return runExploreWith(arguments, stdout, stderr, app.exploreDependencies())
}

// runExploreWith parses the shared campaign grammar and explores the campaign.

func (app application) runPlan(arguments []string, stdout, stderr io.Writer) int {
	return runPlanWith(arguments, stdout, stderr, app.exploreDependencies())
}

// runPlanWith parses the shared campaign grammar and freezes the campaign
// into a portable plan at --output.

func parseCampaignRequest(operation campaignOperation, arguments []string, stdout, stderr io.Writer, dependencies exploreDependencies) (request campaignRequest, status int, ok bool) {
	flags := flag.NewFlagSet("gomad explore", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	strategy := flags.String("strategy", string(runner.StrategySeed), "seed, choice-exploration, or simulation-exploration")
	seeds := flags.String("seeds", "1", "seed set or inclusive ranges")
	count := flags.Uint64("count", 0, "explore seeds 0 through N-1")
	maxRuns := flags.Uint64("max-executions", 0, "maximum exploration candidates")
	maxChoiceDepth := flags.Uint64("max-choice-depth", 0, "maximum forced choice decisions")
	choiceStartOrdinal := flags.Uint64("choice-start-ordinal", 0, "first replay-plan decision ordinal choice exploration expands; inspect --choices lists ordinals")
	maxForcedDecisions := flags.Uint64("max-forced-decisions", 0, "maximum combined forced decisions")
	maxRuntimeDecisions := flags.Uint64("max-runtime-decisions", 0, "maximum runtime decision ordinal")
	maxScenarioDecisions := flags.Uint64("max-scenario-decisions", 0, "maximum scenario decision ordinal")
	maxNetworkDecisions := flags.Uint64("max-network-decisions", 0, "maximum network decision ordinal")
	maxStorageDecisions := flags.Uint64("max-storage-decisions", 0, "maximum storage decision ordinal")
	maxFaultDecisions := flags.Uint64("max-fault-decisions", 0, "maximum fault decision ordinal")
	maxCrashDecisions := flags.Uint64("max-crash-decisions", 0, "maximum crash-state decision ordinal")
	parallel := flags.Int("parallel", min(runtime.NumCPU(), 8), "maximum active targets")
	runTimeout := flags.Duration("execution-timeout", 30*time.Second, "per-execution host deadline")
	overallTimeout := flags.Duration("overall-timeout", 10*time.Minute, "complete exploration host deadline")
	terminateGrace := flags.Duration("terminate-grace", 2*time.Second, "termination grace inside deadlines")
	onFailure := flags.String("on-failure", string(runner.PolicyFirst), "first, budget, or all")
	failureBudget := flags.Uint64("failure-budget", 1, "distinct failure signature threshold")
	artifacts := flags.String("artifacts", ".gomad/artifacts", "artifact root")
	toolchainRoot := flags.String("toolchain-root", "", "absolute pinned toolchain root")
	capabilityMode := flags.String("capability-mode", string(target.CapabilityModeClosure), "closure, linked, or guarded capability assessment")
	jsonOutput := flags.Bool("json", false, "emit stable JSON events")
	planOutput := flags.String("output", "", "campaign plan output")
	choices := flags.Bool("choices", false, "record bounded runtime choices")
	diagnostics := flags.Bool("diagnostics", false, "record runtime-state diagnostics; implies --choices")
	coverage := flags.String("coverage", string(runner.CoverageNone), "none, semantic, choice, or semantic+choice")
	guide := flags.Bool("guide", false, "exclude answered seeds using a bounded coverage corpus")
	guideRegression := flags.Bool("guide-regression", false, "re-run corpus seeds with --guide; fully answered default requests execute zero seeds and exit 0")
	corpus := flags.String("corpus", "", "guided coverage corpus directory")
	keepSuccesses := flags.String("keep-successes", string(runner.KeepSuccessesNone), "none, novel, or all")
	successLimit := flags.Uint64("success-limit", 0, "maximum retained successful executions")
	outputLimit := byteSize(8 << 20)
	worldLimit := byteSize(64 << 20)
	successBytes := byteSize(0)
	choiceLimit := byteSize(8 << 20)
	explorationLimit := byteSize(0)
	explorationResultLimit := byteSize(0)
	flags.Var(&outputLimit, "output-limit", "retained bytes per output stream")
	flags.Var(&worldLimit, "world-transition-limit", "World transition capacity")
	flags.Var(&successBytes, "success-bytes", "total retained successful-execution bytes")
	flags.Var(&choiceLimit, "choice-bytes", "runtime choice trace capacity")
	transcriptLimit := byteSize(64 << 20)
	flags.Var(&transcriptLimit, "io-transcript-bytes", "I/O transcript capacity (64MiB to 1GiB, whole MiB)")
	flags.Var(&explorationLimit, "max-exploration-bytes", "maximum live choice-exploration bytes")
	flags.Var(&explorationResultLimit, "max-exploration-result-bytes", "maximum combined result bytes per candidate")
	var environment stringList
	var buildTags stringList
	var ioROMounts stringList
	var requiredSemanticProbes stringList
	flags.Var(&environment, "env", "target NAME=VALUE")
	flags.Var(&buildTags, "build-tag", "validated Go build tag")
	flags.Var(&ioROMounts, "io-ro-mount", "read-only HOST_DIRECTORY=TARGET_DIRECTORY mapping")
	flags.Var(&requiredSemanticProbes, "require-probe", "required semantic probe (requires --coverage=semantic)")
	workingDir := flags.String("working-dir", "", "absolute target module root (default: the current directory)")
	clockTick := flags.String("clock-tick", record.ClockTickStrict, "virtual-clock tick policy: strict or forward")
	if operation == planCampaign {
		// A portable plan completes all planned work. An explicit
		// --on-failure still parses over this fixed policy, and the plan
		// operation rejects any other.
		_ = flags.Set("on-failure", string(runner.PolicyAll))
	}
	if err := flags.Parse(arguments); err != nil {
		reporter := newExploreReporter(*jsonOutput, stdout, stderr)
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		if !*jsonOutput {
			flags.SetOutput(stderr)
			flags.Usage()
		}
		return campaignRequest{}, 2, false
	}
	reporter := newExploreReporter(*jsonOutput, stdout, stderr)
	if operation != planCampaign && *planOutput != "" {
		if writeErr := reporter.Error("invalid_input", errors.New("--output is only valid with gomad plan")); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	resolvedCapabilityMode, err := parseCapabilityMode(*capabilityMode)
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	var seedsSet, countSet, coverageSet, choiceLimitSet, maxRunsSet, maxChoiceDepthSet, choiceStartOrdinalSet, maxForcedDecisionsSet, maxExplorationBytesSet, maxExplorationResultBytesSet bool
	var runtimeLimitSet, scenarioLimitSet, networkLimitSet, storageLimitSet, faultLimitSet, crashLimitSet bool
	flags.Visit(func(visited *flag.Flag) {
		switch visited.Name {
		case "seeds":
			seedsSet = true
		case "count":
			countSet = true
		case "coverage":
			coverageSet = true
		case "choice-bytes":
			choiceLimitSet = true
		case "max-executions":
			maxRunsSet = true
		case "max-choice-depth":
			maxChoiceDepthSet = true
		case "choice-start-ordinal":
			choiceStartOrdinalSet = true
		case "max-forced-decisions":
			maxForcedDecisionsSet = true
		case "max-exploration-bytes":
			maxExplorationBytesSet = true
		case "max-exploration-result-bytes":
			maxExplorationResultBytesSet = true
		case "max-runtime-decisions":
			runtimeLimitSet = true
		case "max-scenario-decisions":
			scenarioLimitSet = true
		case "max-network-decisions":
			networkLimitSet = true
		case "max-storage-decisions":
			storageLimitSet = true
		case "max-fault-decisions":
			faultLimitSet = true
		case "max-crash-decisions":
			crashLimitSet = true
		}
	})
	resolvedStrategy, resolvedChoices, err := resolveExploreStrategy(exploreStrategyOptions{
		Value: *strategy, Seeds: *seeds, CountSet: countSet, Guide: *guide, Choices: *choices || *diagnostics,
		MaxExecutions: *maxRuns, MaxChoiceDepth: *maxChoiceDepth, MaxForcedDecisions: *maxForcedDecisions,
		MaxExplorationBytes: explorationLimit, MaxExplorationResultBytes: explorationResultLimit,
		SimulationDimensionLimits: runner.SimulationDimensionLimits{
			Runtime: *maxRuntimeDecisions, Scenario: *maxScenarioDecisions, Network: *maxNetworkDecisions,
			Storage: *maxStorageDecisions, Fault: *maxFaultDecisions, Crash: *maxCrashDecisions,
		},
		MaxExecutionsSet: maxRunsSet, MaxChoiceDepthSet: maxChoiceDepthSet, ChoiceStartOrdinalSet: choiceStartOrdinalSet, MaxForcedDecisionsSet: maxForcedDecisionsSet,
		MaxExplorationBytesSet: maxExplorationBytesSet, MaxExplorationResultBytesSet: maxExplorationResultBytesSet,
		RuntimeLimitSet: runtimeLimitSet, ScenarioLimitSet: scenarioLimitSet, NetworkLimitSet: networkLimitSet,
		StorageLimitSet: storageLimitSet, FaultLimitSet: faultLimitSet, CrashLimitSet: crashLimitSet,
	})
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	resolvedSeeds, err := resolveExploreSeeds(*seeds, *count, seedsSet, countSet)
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	if *guideRegression && !*guide {
		if err := reporter.Error("invalid_input", errors.New("--guide-regression requires --guide")); err != nil {
			fmt.Fprintln(stderr, err)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	resolvedCoverage, err := resolveExploreGuidance(*guide, *corpus, *coverage, coverageSet)
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	coverageMode, err := resolveExploreCoverage(resolvedCoverage, requiredSemanticProbes)
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	if *diagnostics && resolvedStrategy != runner.StrategySeed {
		if err := reporter.Error("invalid_input", errors.New("--diagnostics requires the seed strategy; forced-prefix exploration is unsupported")); err != nil {
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	resolvedChoiceLimit, err := resolveChoiceTrace(resolvedChoices, choiceLimit, choiceLimitSet)
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	if err := runner.ValidateChoiceCoverage(coverageMode, resolvedChoiceLimit); err != nil {
		if writeErr := reporter.Error("invalid_input", fmt.Errorf("--coverage=%s requires --choices", coverageMode)); writeErr != nil {
			if _, printErr := fmt.Fprintln(stderr, writeErr); printErr != nil {
				return campaignRequest{}, 3, false
			}
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	parsedTarget, err := parseTarget(flags.Args())
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	workingDirectory, err := resolveWorkingDirectory(*workingDir, dependencies.workingDirectory)
	if err != nil {
		var invalid invalidWorkingDirectoryError
		if errors.As(err, &invalid) {
			if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
				fmt.Fprintln(stderr, writeErr)
				return campaignRequest{}, 3, false
			}
			return campaignRequest{}, 2, false
		}
		if writeErr := reporter.Error("runner_failure", fmt.Errorf("resolve working directory: %w", err)); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
		}
		return campaignRequest{}, 3, false
	}
	installed, err := dependencies.install(*toolchainRoot)
	if err != nil {
		if writeErr := reporter.Error("runner_failure", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
		}
		return campaignRequest{}, 3, false
	}
	config := runner.CampaignSpec{
		Strategy: resolvedStrategy, Seeds: resolvedSeeds, Parallel: *parallel, ExecutionTimeout: *runTimeout, OverallTimeout: *overallTimeout, TerminateGrace: *terminateGrace,
		OnFailure: runner.FailurePolicy(*onFailure), FailureBudget: *failureBudget, OutputLimit: uint64(outputLimit), WorldTransitionLimit: uint64(worldLimit),
		Diagnostics: *diagnostics, ChoiceTraceLimit: resolvedChoiceLimit, ClockTick: *clockTick, IOTranscriptLimit: uint64(transcriptLimit), MaxExecutions: *maxRuns, MaxChoiceDepth: *maxChoiceDepth, ChoiceStartOrdinal: *choiceStartOrdinal, MaxForcedDecisions: *maxForcedDecisions,
		MaxExplorationBytes: uint64(explorationLimit), MaxExplorationResultBytes: uint64(explorationResultLimit),
		SimulationDimensionLimits: runner.SimulationDimensionLimits{
			Runtime: *maxRuntimeDecisions, Scenario: *maxScenarioDecisions, Network: *maxNetworkDecisions,
			Storage: *maxStorageDecisions, Fault: *maxFaultDecisions, Crash: *maxCrashDecisions,
		},
		Artifacts: *artifacts, Environment: environment, IOROMounts: ioROMounts, SupervisorCommand: installed.supervisorCommand(), CoordinatorCommand: installed.coordinatorCommand(), RunnerBuild: installed.runnerBuild,
		Coverage: coverageMode, RequiredSemanticProbes: requiredSemanticProbes,
		KeepSuccesses: runner.KeepSuccesses(*keepSuccesses), SuccessArtifactLimit: *successLimit, SuccessBytesLimit: uint64(successBytes),
		Guide: *guide, GuideRegression: *guideRegression, Corpus: *corpus,
		Progress: reporter.Progress, ProgressInterval: 5 * time.Second,
		Target: target.Spec{
			Kind: parsedTarget.kind, Source: parsedTarget.source, Provenance: parsedTarget.provenance, Args: parsedTarget.arguments,
			BuildTags: buildTags, WorkingDir: workingDirectory, ToolchainRoot: installed.toolchainRoot, CapabilityMode: resolvedCapabilityMode,
		},
	}
	return campaignRequest{campaign: config, output: *planOutput, json: *jsonOutput, reporter: reporter}, 0, true
}

