	Value                        string
	Seeds                        string
	CountSet                     bool
	Guide                        bool
	Choices                      bool
	MaxExecutions                uint64
	MaxChoiceDepth               uint64
	MaxForcedDecisions           uint64
	MaxExplorationBytes          byteSize
	MaxExplorationResultBytes    byteSize
	SimulationDimensionLimits    runner.SimulationDimensionLimits
	MaxExecutionsSet             bool
	MaxChoiceDepthSet            bool
	ChoiceStartOrdinalSet        bool
	MaxForcedDecisionsSet        bool
	MaxExplorationBytesSet       bool
	MaxExplorationResultBytesSet bool
	RuntimeLimitSet              bool
	ScenarioLimitSet             bool
	NetworkLimitSet              bool
	StorageLimitSet              bool
	FaultLimitSet                bool
	CrashLimitSet                bool
}

// resolveExploreStrategy checks the exploration flags given for the strategy
// Runner reads from --strategy, and reports whether the strategy records
// choices.

func (app application) runReplay(arguments []string, stdout, stderr io.Writer) int {
	return runReplayWith(arguments, stdout, stderr, replayDependencies{install: app.install, replay: runner.Replay})
}

func runReplayWith(arguments []string, stdout, stderr io.Writer, dependencies replayDependencies) int {
	flags := flag.NewFlagSet("gomad replay", flag.ContinueOnError)
	flags.SetOutput(stderr)
	verifyOnly := flags.Bool("verify-only", false, "validate without executing the target")
	toolchainRoot := flags.String("toolchain-root", "", "absolute pinned toolchain root")
	observedDir := flags.String("observed", "", "directory that receives the replayed target's stdout and stderr")
	if err := flags.Parse(arguments); err != nil {
		return 2
	}
	if flags.NArg() != 1 {
		fmt.Fprint(stderr, usage)
		return 2
	}
	installed, err := dependencies.install(*toolchainRoot)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 3
	}
	result, err := dependencies.replay(context.Background(), runner.ReplaySpec{
		ArtifactPath: flags.Arg(0), VerifyOnly: *verifyOnly, ToolchainRoot: installed.toolchainRoot, ObservedDir: *observedDir, SupervisorCommand: installed.supervisorCommand(),
	})
	if err != nil {
		var preflightError *runner.ReplayPreflightError
		if errors.As(err, &preflightError) {
			fmt.Fprintln(stderr, err)
			return 2
		}
		fmt.Fprintln(stderr, err)
		return 3
	}
	if *verifyOnly {
		fmt.Fprintf(stdout, "gomad: verified %s\n", result.Artifact.Path)
		return 0
	}
	status, err := reportReplayResult(stdout, result)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 3
	}
	return status
}

type minimizeDependencies struct {
	install  func(string) (installation, error)
	minimize func(context.Context, runner.MinimizeSpec) (runner.MinimizeResult, error)
}

func (app application) runMinimize(arguments []string, stdout, stderr io.Writer) int {
	return runMinimizeWith(arguments, stdout, stderr, minimizeDependencies{install: app.install, minimize: runner.Minimize})
}

func runMinimizeWith(arguments []string, stdout, stderr io.Writer, dependencies minimizeDependencies) int {
	flags := flag.NewFlagSet("gomad minimize", flag.ContinueOnError)
	flags.SetOutput(stderr)
	jsonOutput := flags.Bool("json", false, "emit stable JSON")
	artifacts := flags.String("artifacts", ".gomad/artifacts", "artifact root")
	toolchainRoot := flags.String("toolchain-root", "", "absolute pinned toolchain root")
	attemptBudget := flags.Uint64("attempt-budget", 64, "maximum fresh-process minimization candidates")
	resume := flags.Bool("resume", false, "continue this artifact's interrupted minimization from its state under the artifact root")
	maximumBytes := byteSize(0)
	flags.Var(&maximumBytes, "max-bytes", "maximum minimized artifact bytes")
	if err := flags.Parse(arguments); err != nil {
		return 2
	}
	if flags.NArg() != 1 || *attemptBudget == 0 {
		return writeCommandError(stderr, 2, "%s", usage)
	}
	artifactRoot, err := filepath.Abs(*artifacts)
	if err != nil {
		return writeCommandError(stderr, 2, "resolve artifact directory: %v\n", err)
	}
	installed, err := dependencies.install(*toolchainRoot)
	if err != nil {
		return writeCommandError(stderr, 3, "%v\n", err)
	}
	result, err := dependencies.minimize(context.Background(), runner.MinimizeSpec{
		ArtifactPath: flags.Arg(0), OutputRoot: filepath.Join(artifactRoot, "minimized"),
		AttemptBudget: *attemptBudget, MaximumBytes: uint64(maximumBytes), ToolchainRoot: installed.toolchainRoot,
		SupervisorCommand: installed.supervisorCommand(), Resume: *resume,
	})
	if err != nil {
		var preflight *runner.ReplayPreflightError
		if errors.As(err, &preflight) {
			return writeCommandError(stderr, 2, "%v\n", err)
		}
		return writeCommandError(stderr, 3, "%v\n", err)
	}
	if *jsonOutput {
		encoded, err := json.Marshal(struct {
			ArtifactPath  string                         `json:"artifact_path"`
			RecordHash    record.SHA256                  `json:"record_hash"`
			Changed       bool                           `json:"changed"`
			Attempts      uint64                         `json:"attempts"`
			AttemptBudget uint64                         `json:"attempt_budget"`
			Accepted      []record.MinimizationReduction `json:"accepted"`
			StopReason    string                         `json:"stop_reason"`
		}{
			ArtifactPath: result.Artifact.Path, RecordHash: result.Artifact.Manifest.RecordHash, Changed: result.Changed,
			Attempts: result.Attempts, AttemptBudget: result.AttemptBudget, Accepted: result.Accepted, StopReason: result.StopReason,
		})
		if err != nil {
			return writeCommandError(stderr, 3, "encode minimization result: %v\n", err)
		}
		if _, err := fmt.Fprintf(stdout, "%s\n", encoded); err != nil {
			return 3
		}
		return 0
	}
	if _, err := fmt.Fprintf(
		stdout, "gomad minimize: changed=%t attempts=%d/%d accepted=%d stop=%s artifact=%s\n",
		result.Changed, result.Attempts, result.AttemptBudget, len(result.Accepted), result.StopReason, result.Artifact.Path,
	); err != nil {
		return 3
	}
	return 0
}

func (app application) runQualify(arguments []string, stdout, stderr io.Writer) int {
	return runQualifyWith(arguments, stdout, stderr, qualifyDependencies{
		install: app.install, workingDirectory: os.Getwd, workload: qualificationworkload.Run,
	})
}

func runQualifyWith(arguments []string, stdout, stderr io.Writer, dependencies qualifyDependencies) int {
	flags := flag.NewFlagSet("gomad qualify", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	seed := flags.Uint64("seed", 1, "schedule seed")
	repeat := flags.Uint64("repeat", 2, "fresh same-seed repetitions")
	runTimeout := flags.Duration("execution-timeout", 30*time.Second, "per-execution host deadline")
	overallTimeout := flags.Duration("overall-timeout", 10*time.Minute, "complete qualification host deadline")
	terminateGrace := flags.Duration("terminate-grace", 2*time.Second, "termination grace inside deadlines")
	artifacts := flags.String("artifacts", ".gomad/artifacts", "artifact and qualification report root")
	toolchainRoot := flags.String("toolchain-root", "", "absolute pinned toolchain root")
	capabilityMode := flags.String("capability-mode", string(target.CapabilityModeClosure), "closure, linked, or guarded capability assessment")
	jsonOutput := flags.Bool("json", false, "emit stable JSON events")
	choices := flags.Bool("choices", false, "record bounded runtime choices")
	diagnostics := flags.Bool("diagnostics", false, "record runtime-state diagnostics for fresh runs; implies --choices")
	replaySuccesses := flags.Bool("replay-successes", false, "retain and replay every successful repetition")
	successLimit := flags.Uint64("success-limit", 0, "maximum retained successful executions per repetition")
	outputLimit := byteSize(8 << 20)
	worldLimit := byteSize(64 << 20)
	successBytes := byteSize(0)
	choiceLimit := byteSize(8 << 20)
	flags.Var(&outputLimit, "output-limit", "retained bytes per output stream")
	flags.Var(&worldLimit, "world-transition-limit", "World transition capacity")
	flags.Var(&successBytes, "success-bytes", "retained successful-execution bytes per repetition")
	flags.Var(&choiceLimit, "choice-bytes", "runtime choice trace capacity")
	transcriptLimit := byteSize(64 << 20)
	flags.Var(&transcriptLimit, "io-transcript-bytes", "I/O transcript capacity (64MiB to 1GiB, whole MiB)")
	var environment stringList
	var buildTags stringList
	var ioROMounts stringList
	var requiredSemanticProbes stringList
	flags.Var(&environment, "env", "target NAME=VALUE")
	flags.Var(&buildTags, "build-tag", "validated Go build tag")
	flags.Var(&ioROMounts, "io-ro-mount", "read-only HOST_DIRECTORY=TARGET_DIRECTORY mapping")
	flags.Var(&requiredSemanticProbes, "require-probe", "required semantic probe")
	workingDir := flags.String("working-dir", "", "absolute target module root (default: the current directory)")
	clockTick := flags.String("clock-tick", record.ClockTickStrict, "virtual-clock tick policy: strict or forward")
	if err := flags.Parse(arguments); err != nil {
		reporter := newQualifyReporter(*jsonOutput, stdout, stderr)
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return 3
		}
		if !*jsonOutput {
			flags.SetOutput(stderr)
			flags.Usage()
		}
		return 2
	}
	reporter := newQualifyReporter(*jsonOutput, stdout, stderr)
	resolvedCapabilityMode, err := parseCapabilityMode(*capabilityMode)
	if err != nil {
		return reportQualifyInputError(reporter, stderr, err)
	}
	choiceLimitSet := false
	flags.Visit(func(visited *flag.Flag) {
		if visited.Name == "choice-bytes" {
			choiceLimitSet = true
		}
	})
	resolvedChoiceLimit, err := resolveChoiceTrace(*choices || *diagnostics, choiceLimit, choiceLimitSet)
	if err != nil {
		return reportQualifyInputError(reporter, stderr, err)
	}
	if *repeat < 2 || *repeat > maximumQualificationRepeats {
		return reportQualifyInputError(reporter, stderr, fmt.Errorf("--repeat must be between 2 and %d", maximumQualificationRepeats))
	}
	if *replaySuccesses && (*successLimit == 0 || successBytes == 0) {
		return reportQualifyInputError(reporter, stderr, errors.New("--replay-successes requires explicit --success-limit and --success-bytes bounds"))
	}
	if !*replaySuccesses && (*successLimit != 0 || successBytes != 0) {
		return reportQualifyInputError(reporter, stderr, errors.New("--success-limit and --success-bytes require --replay-successes"))
	}
	coverage := runner.CoverageSemantic
	if *choices || *diagnostics {
		coverage = runner.CoverageSemanticChoice
	}
	if _, err := resolveExploreCoverage(string(coverage), requiredSemanticProbes); err != nil {
		return reportQualifyInputError(reporter, stderr, err)
	}
	parsedTarget, err := parseTarget(flags.Args())
	if err != nil {
		return reportQualifyInputError(reporter, stderr, err)
	}
	workingDirectory, err := resolveWorkingDirectory(*workingDir, dependencies.workingDirectory)
	if err != nil {
		var invalid invalidWorkingDirectoryError
		if errors.As(err, &invalid) {
			return reportQualifyInputError(reporter, stderr, err)
		}
		return reportQualifyUnretainedError(reporter, stderr, "runner_failure", fmt.Errorf("resolve working directory: %w", err), 3)
	}
	installed, err := dependencies.install(*toolchainRoot)
	if err != nil {
		return reportQualifyUnretainedError(reporter, stderr, "runner_failure", err, 3)
	}
	command := append([]string{"gomad", "qualify"}, arguments...)
	config := runner.CampaignSpec{
		Seeds: strconv.FormatUint(*seed, 10), Parallel: 1, ExecutionTimeout: *runTimeout, OverallTimeout: *overallTimeout, TerminateGrace: *terminateGrace,
		OnFailure: runner.PolicyAll, FailureBudget: 1, OutputLimit: uint64(outputLimit), WorldTransitionLimit: uint64(worldLimit),
		Diagnostics: *diagnostics, ChoiceTraceLimit: resolvedChoiceLimit, ClockTick: *clockTick, IOTranscriptLimit: uint64(transcriptLimit),
		Artifacts: *artifacts, Environment: environment, IOROMounts: ioROMounts,
		SupervisorCommand: installed.supervisorCommand(), CoordinatorCommand: installed.coordinatorCommand(), RunnerBuild: installed.runnerBuild,
		Coverage: coverage, RequiredSemanticProbes: requiredSemanticProbes, CollectExecutionEvidence: true,
		Target: target.Spec{
			Kind: parsedTarget.kind, Source: parsedTarget.source, Provenance: parsedTarget.provenance, Args: parsedTarget.arguments,
			BuildTags: buildTags, WorkingDir: workingDirectory, ToolchainRoot: installed.toolchainRoot, CapabilityMode: resolvedCapabilityMode,
		},
	}
	if *replaySuccesses {
		config.KeepSuccesses = runner.KeepSuccessesAll
		config.SuccessArtifactLimit = *successLimit
		config.SuccessBytesLimit = uint64(successBytes)
	}
	ctx, cancel := context.WithTimeout(context.Background(), *overallTimeout)
	defer cancel()
	runWorkload := dependencies.workload
	if runWorkload == nil {
		runWorkload = qualificationworkload.Run
	}
	result, err := runWorkload(ctx, qualificationworkload.Spec{
		Command: command, Seed: *seed, Repeat: *repeat, ArtifactRoot: *artifacts, Campaign: config,
		Replay:          runner.ReplaySpec{ToolchainRoot: installed.toolchainRoot, SupervisorCommand: installed.supervisorCommand()},
		ReplaySuccesses: *replaySuccesses,
		Progress: func(event qualificationworkload.Progress) error {
			return reporter.Progress(event.Iteration, event.Repeat)
		},
		Explore: dependencies.run, ReplayArtifact: dependencies.replay, Write: dependencies.write,
	})
	if err != nil {
		return reportQualifyUnretainedError(reporter, stderr, "runner_failure", err, 3)
	}
	if result.ChoiceTrace != nil && !*jsonOutput {
		if _, err := fmt.Fprintf(stderr, "gomad:%s\n", formatChoiceTrace(result.ChoiceTrace)); err != nil {
			return 3
		}
	}
	if err := reporter.Result(result.Report, result.ReportPath); err != nil {
		fmt.Fprintln(stderr, err)
		return 3
	}
	return qualification.ExitStatus(qualification.ClassifyQualification(result.Report))
}

func (app application) runQualifySet(arguments []string, stdout, stderr io.Writer) int {
	return runQualifySetWith(arguments, stdout, stderr, qualifySetDependencies{
		executable: app.executablePath, load: qualificationset.LoadManifest, run: qualificationset.Run,
	})
}

func (app application) runResume(arguments []string, stdout, stderr io.Writer) int {
	return runResumeWith(arguments, stdout, stderr, resumeDependencies{install: app.install, run: runner.Resume})
}

func runResumeWith(arguments []string, stdout, stderr io.Writer, dependencies resumeDependencies) int {
	flags := flag.NewFlagSet("gomad resume", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	guideRegression := flags.Bool("guide-regression", false, "require the recorded guidance regression mode")
	jsonOutput := flags.Bool("json", false, "emit stable JSON events")
	toolchainRoot := flags.String("toolchain-root", "", "absolute pinned toolchain root")
	if err := flags.Parse(arguments); err != nil {
		reporter := newExploreReporter(*jsonOutput, stdout, stderr)
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return 3
		}
		if !*jsonOutput {
			flags.SetOutput(stderr)
			flags.Usage()
		}
		return 2
	}
	reporter := newExploreReporter(*jsonOutput, stdout, stderr)
	if flags.NArg() != 1 || flags.Arg(0) == "" {
		if err := reporter.Error("invalid_input", errors.New("resume requires one interrupted campaign path")); err != nil {
			fmt.Fprintln(stderr, err)
			return 3
		}
		return 2
	}
	installed, err := dependencies.install(*toolchainRoot)
	if err != nil {
		if writeErr := reporter.Error("runner_failure", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
		}
		return 3
	}
	var regressionOverride *bool
	flags.Visit(func(value *flag.Flag) {
		if value.Name == "guide-regression" {
			regressionOverride = guideRegression
		}
	})
	summary, err := dependencies.run(context.Background(), runner.ResumeSpec{
		CampaignPath: flags.Arg(0), GuideRegression: regressionOverride, RunnerBuild: installed.runnerBuild, ToolchainRoot: installed.toolchainRoot,
		SupervisorCommand: installed.supervisorCommand(), CoordinatorCommand: installed.coordinatorCommand(),
		Progress: reporter.Progress, ProgressInterval: 5 * time.Second,
	})
	if err != nil {
		classification := classifyResumeError(err)
		if writeErr := reporter.Error(classification, err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return 3
		}
		return exploreErrorStatus(classification)
	}
	if err := reporter.Result(summary); err != nil {
		fmt.Fprintln(stderr, err)
		return 3
	}
	return exploreSummaryStatus(summary)
}

